from pathlib import Path
import concurrent.futures,hashlib,json,os,subprocess,sys,time
ROOT=Path('/private/tmp/vellum-p9-integration')
OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'scripts'))
from child_process import run_child

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def write(n,v):(OUT/n).write_text(json.dumps(v,indent=2)+'\n')
def inputs():
 data={}
 for p in sorted(ROOT.rglob('*')):
  if not p.is_file():continue
  rel=p.relative_to(ROOT); parts=rel.parts
  if '.git' in parts or '__pycache__' in parts or parts[0] in ('docs','specs'):continue
  if 'build' in parts and not (parts[:4]==('drivers','cogent','build','upstream') or parts[:4]==('drivers','cogent','build','typesetting')):continue
  if p.suffix=='.md' or p.name=='.DS_Store':continue
  data[str(rel)]=sha(p)
 return data

def run(spec):
 name,cwd,args,timeout=spec; log=OUT/(name+'.log');start=time.monotonic()
 with log.open('wb') as f:
  f.write((json.dumps({'command':args,'cwd':str(cwd)})+'\n').encode());f.flush()
  try:code=run_child(args,cwd=cwd,stdout=f,stderr=subprocess.STDOUT,timeout=timeout).returncode
  except subprocess.TimeoutExpired:code=124;f.write(b'QUALIFICATION PROCESS TIMEOUT\n')
 result={'name':name,'command':args,'cwd':str(cwd),'exit_code':code,'elapsed_seconds':round(time.monotonic()-start,3),'log':str(log),'log_sha256':sha(log)}
 write(name+'-exit.json',result)
 return result

def main():
 before=inputs();write('source-before.json',before)
 proofs=[]
 for path in ['/private/tmp/vellum-p9-native/qualification-v2.json','/private/tmp/vellum-p9-timers/qualification-v2.json','/private/tmp/vellum-p9-managed/acceptance-v2/qualification.json','/private/tmp/vellum-p9-replay/acceptance/qualification-v6.json','/private/tmp/vellum-p9-native-corrections/qualification.json','/private/tmp/vellum-p9-capture-followup/qualification.json']:
  p=Path(path)
  if p.exists():proofs.append({'path':path,'sha256':sha(p)})
 expected={}
 for path in ['/private/tmp/vellum-p9-native/patch30-manifest-v2.json','/private/tmp/vellum-p9-timers/patch31-manifest-v2.json']:
  v=json.loads(Path(path).read_text());write(Path(path).name,v)
 # Both stages are reproduced by prepare.py; exact output hashes are committed contracts.
 for stage in ('manualrouting','ownedtimers','checkedmanual'):
  v=json.loads((ROOT/('drivers/cogent/native/patches/'+stage+'/output-hashes.json')).read_text());expected.update(v)
 mismatches={p:sha(ROOT/'drivers/cogent/build/upstream'/p) for p,h in expected.items() if sha(ROOT/'drivers/cogent/build/upstream'/p)!=h}
 if mismatches:raise ValueError(mismatches)
 write('prepared-stage30-32.json',{'result':'PASS','file_count':len(expected),'files':expected})
 specs=[('full-gate',ROOT,['./scripts/check.sh'],600),('runner-race20',ROOT,['go','test','-race','-count=20','./replay'],180),('actual-consumer-race3',ROOT/'examples/replay',['go','test','-race','-tags','offscreen','-count=3','-timeout=180s','./...'],240)]
 with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:checks=list(pool.map(run,specs))
 build=run(('native-editor-build',ROOT/'examples/editor',['go','build','-race','-o',str(OUT/'editor'),'.'],300));checks.append(build)
 if build['exit_code']==0:
  checks.append(run(('native-editor-smoke',OUT,[str(OUT/'editor'),'-smoke'],90)))
  text=(OUT/'native-editor-smoke.log').read_text(); markers=[s for s in text.splitlines() if s.startswith('EDITOR_SMOKE_PASS:')];stages=[s[6:] for s in text.splitlines() if s.startswith('stage ')]
  write('native-editor.json',{'binary_sha256':sha(OUT/'editor'),'markers':markers,'stages':stages,'scope':'actual deterministic Cocoa protocol and native AX methods; no human IME/VoiceOver or external AX rerun'})
  if len(markers)!=1 or not {'native-ready','settle-admission-refusal','admitted-settle-cancellation','controlled-field-focus-handoff','composition-one-history-entry','cancel-preedit','settled-save-exact-bytes','open-install-native-refresh','bounded-native-refusal','owner-edit-remount-and-focus-handoff','native-range-geometry-wrap-bidi','save-close-native-preedit-during-write','save-close-refusal-and-terminal-teardown'}.issubset(stages):checks.append({'name':'native-editor-acceptance','exit_code':1})
 checks.append(run(('native-replay-build',ROOT/'examples/replay',['go','build','-race','-tags','offscreen','-o',str(OUT/'replay-native'),'./cmd/native'],300)))
 if checks[-1]['exit_code']==0:
  outputs=[]
  for batch in (1,7,64):
   c=run(('native-replay-'+str(batch),ROOT,[str(OUT/'replay-native'),'-batch',str(batch)],90));checks.append(c)
   log=(OUT/('native-replay-'+str(batch)+'.log')).read_text();data=json.loads(log[log.index('\n')+1:]);write('native-replay-'+str(batch)+'.json',data);outputs.append(data)
  results=[x['Result'] for x in outputs]
  checkpoints=[x['Checkpoints'] for x in results]
  if not all(x==checkpoints[0] for x in checkpoints):raise ValueError('Different batch checkpoints')
  write('batch-equivalence.json',{'result':'PASS','batches':[1,7,64],'operations':51,'captures':len(checkpoints[0]),'checkpoints_equal':True,'quiescent_now':[r['QuiescentNow'] for r in results],'binary_sha256':sha(OUT/'replay-native'),'record_sha256':sha(ROOT/'examples/replay/native-record.json')})
 after=inputs();write('source-after.json',after)
 changed={p:[h,after.get(p)] for p,h in before.items() if after.get(p)!=h};changed.update({p:[None,h] for p,h in after.items() if p not in before})
 result={'result':'PASS' if not changed and all(x['exit_code']==0 for x in checks) else 'FAIL','root':str(ROOT),'base_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'compiler':subprocess.check_output(['go','version'],text=True).strip(),'collector_sha256':sha(Path(__file__)),'input_count':len(before),'source_before_sha256':sha(OUT/'source-before.json'),'source_after_sha256':sha(OUT/'source-after.json'),'changed_inputs':changed,'checks':checks,'prepared_files':len(expected),'independent_foundation_proofs':proofs,'scope':'one bounded fixed actual software UI replay; explicit owned widget timers; existing Cocoa editor regression; full P9/native services/GPU/performance remain open','historical_sandbox_gate':{'path':'/private/tmp/vellum-p9-integration-check.log','sha256':sha('/private/tmp/vellum-p9-integration-check.log'),'exit_code':1,'reason':'ps forbidden by sandbox in existing child_process_test.py'}}
 write('qualification.json',result);print(json.dumps({'result':result['result'],'input_count':len(before),'changed':len(changed),'checks':[{'name':x['name'],'exit_code':x['exit_code']} for x in checks]}),flush=True)
 raise SystemExit(0 if result['result']=='PASS' else 1)
if __name__=='__main__':main()

